-- 051: Seed the 12 code-authoritative learning fields for all 40 country pages.
-- Plain text only; visual variants, section order, routes, and SEO remain code-owned.
-- Conflicts are left untouched to preserve any reviewed/admin-edited value.
BEGIN;
DO $$ DECLARE n integer; BEGIN
  SELECT count(*) INTO n FROM public.site_areas WHERE area_type = 'country' AND slug IN ('argentina', 'australia', 'austria', 'bahrain', 'belgium', 'brazil', 'canada', 'china', 'colombia', 'denmark', 'finland', 'france', 'germany', 'greece', 'indonesia', 'italy', 'jordan', 'kuwait', 'malaysia', 'mexico', 'netherlands', 'new-zealand', 'nigeria', 'norway', 'oman', 'poland', 'portugal', 'qatar', 'russia', 'saudi-arabia', 'senegal', 'south-africa', 'spain', 'sweden', 'switzerland', 'turkey', 'united-arab-emirates', 'united-kingdom', 'united-states', 'venezuela');
  IF n <> 40 THEN RAISE EXCEPTION 'Expected 40 country areas, found %; aborting seed', n; END IF;
END $$;

