WHERE a.area_type = 'country'
ON CONFLICT (area_id, content_key) DO NOTHING;

DO $$ DECLARE n integer; BEGIN
  SELECT count(*) INTO n FROM public.area_content c
  JOIN public.site_areas a ON a.id = c.area_id
  WHERE a.area_type = 'country' AND a.slug IN ('argentina', 'australia', 'austria', 'bahrain', 'belgium', 'brazil', 'canada', 'china', 'colombia', 'denmark', 'finland', 'france', 'germany', 'greece', 'indonesia', 'italy', 'jordan', 'kuwait', 'malaysia', 'mexico', 'netherlands', 'new-zealand', 'nigeria', 'norway', 'oman', 'poland', 'portugal', 'qatar', 'russia', 'saudi-arabia', 'senegal', 'south-africa', 'spain', 'sweden', 'switzerland', 'turkey', 'united-arab-emirates', 'united-kingdom', 'united-states', 'venezuela')
    AND c.content_key IN ('learning_name', 'learning_local_title', 'learning_local_description', 'learning_quran_title', 'learning_quran_body', 'learning_arabic_title', 'learning_arabic_body', 'learning_quran_article_title', 'learning_quran_article_body', 'learning_arabic_article_title', 'learning_arabic_article_body', 'learning_teacher_angle')
    AND c.section = 'learning' AND c.is_active = TRUE AND NULLIF(btrim(c.content_ar), '') IS NOT NULL;
  IF n <> 480 THEN RAISE EXCEPTION 'Expected 480 active learning fields, found %; transaction rolled back', n; END IF;
END $$;
COMMIT;
